using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class UnitDirectiveCancellationBoundaryTests
{
 static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
 static NewMilitaryInput Input(WorldSession s,NewMilitaryAction action)=>new(new("request:unit-recipient/"+s.Revision+"/"+action),action);
 static void Send(WorldSession s,NewMilitaryAction action,long amount=0){var result=s.DecideNewMilitary(Input(s,action) with{Amount=amount},s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);}
 static void Open(WorldSession s){foreach(var m in s.GetActorView(s.PlayerControl).Messages.Where(m=>m.KnownBody==null).ToArray())Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,m.Id,s.Revision).Code);}
 static WorldSession Away(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu",role:StartTemplate.Retainer,lord:"person:shingen")]);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Request) with{ObservationPolicy=NewGameMilitary.ObservationContract},s.PlayerControl,s.Revision).Code);At(s,2);Open(s);Send(s,NewMilitaryAction.Accept);At(s,4);Open(s);Send(s,NewMilitaryAction.Pickup);Send(s,NewMilitaryAction.Load,100000);Send(s,NewMilitaryAction.Deploy);var a=NewGameMilitary.Anchor(s.DiagnosticSnapshot());Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.Form) with{A=new(a.X+90000,a.Y-10000),B=new(a.X+90000,a.Y+10000)},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Max(l=>l.EndAt)+1);Send(s,NewMilitaryAction.Handoff);Send(s,NewMilitaryAction.Withdraw);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Max(l=>l.EndAt)+1);return s;}
 static NewMilitaryInput Query(WorldSession s,int unit)=>Input(s,NewMilitaryAction.InquireUnitKnown) with{InquiryTarget=new(NewGameMilitary.UnitRecipientContract,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[unit])!),PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};
 static TroopDispatch Dispatch(WorldSession s,int unit){var i=Query(s,unit);var r=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitInquiry!.Dispatches.Last();}
 static UnitPostInquiryAnswer Answer(ContractWorld w,TroopReceipt receipt)=>ContractJson.Read<UnitPostInquiryAnswer>(System.Text.Encoding.UTF8.GetBytes(w.Messaging.Messages.Single(m=>m.Id==receipt.ReplyMessage).Body));

 static NewMilitaryInput Directive(WorldSession s,int unit,UnitDirectiveKind kind){var w=s.DiagnosticSnapshot();var k=NewGameMilitary.SelectKnownTarget(w,NewGameMilitary.UnitIds[unit])!;return Input(s,NewMilitaryAction.SendUnitDirective) with{Directive=new(NewGameMilitary.UnitDirectiveContract,k,kind,kind==UnitDirectiveKind.Move?new(k.Position.X+8000,k.Position.Y):null),DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract,OriginalPolicy=NewGameMilitary.UnitDirectiveHoldingContract};}

 static TroopDispatch FailedOriginal(WorldSession s,bool learn=true,int index=1,UnitDirectiveKind kind=UnitDirectiveKind.Move,bool holding=true){Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,index,kind) with{OriginalPolicy=holding?NewGameMilitary.UnitDirectiveHoldingContract:null};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,root.DueAt);var r=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Receipts.Last();Assert.False(r.Delivered);if(learn)At(s,r.ReplyDueAt);return root;}
 static void HomeUnits(WorldSession s){long end=s.DiagnosticSnapshot().NewMilitary!.Orders.Last().Routes.SelectMany(r=>r).Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max();At(s,Math.Max(s.Seconds,end+2));}
 static NewMilitaryInput Retry(WorldSession s,TroopDispatch root)=>Input(s,NewMilitaryAction.RetryUnitDirective) with{DirectiveRetry=new(NewGameMilitary.UnitDirectiveRetryContract,root.Id,NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),root.Recipient)!),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};

 static UnitHeldTransfer Handoff(WorldSession s,TroopDispatch root){var paper=NewGameMilitary.SelectDirectivePaper(s.DiagnosticSnapshot(),root.Id);Assert.NotNull(paper);var input=Input(s,NewMilitaryAction.DeliverHeldUnitDirective) with{DirectiveHandoff=paper};var result=s.DecideNewMilitary(input,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();}
 static TroopDispatch Cancel(WorldSession s,TroopDispatch root,long? effective=null){var w=s.DiagnosticSnapshot();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,effective??s.Seconds);var i=Input(s,NewMilitaryAction.CancelUnitDirective) with{DirectiveCancellation=p,DeliverBy=s.Seconds+600,PostPolicy=NewGameMilitary.UnitReplyRecoveryContract,TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract};var result=s.DecideNewMilitary(i,s.PlayerControl,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);return s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Dispatches.Last();}
 static void MovePerson(WorldSession s,FieldPoint p){Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Input(s,NewMilitaryAction.PersonalMove) with{A=p},s.PlayerControl,s.Revision).Code);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Journeys.Last().Route.Select(l=>l.EndAt).DefaultIfEmpty(s.Seconds).Max()+1);}
 [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)]public void InvalidCancellationIsAtomic(int kind){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();var root=w.NewMilitary!.UnitDirective!.Dispatches.Last();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,s.Seconds);var x=Input(s,NewMilitaryAction.CancelUnitDirective) with{DirectiveCancellation=p};x=kind switch{0=>x with{DirectiveCancellation=p with{Contract="unknown"}},1=>x with{DirectiveCancellation=p with{Original=new("request:foreign-original")}},2=>x with{DirectiveCancellation=p with{Known=p.Known with{Unit=NewGameMilitary.UnitIds[2]}}},3=>x with{DirectiveCancellation=p with{Known=p.Known with{Position=new(p.Known.Position.X+1,p.Known.Position.Y)}}},4=>x with{DirectiveCancellation=p with{EffectiveAt=s.Seconds-1}},5=>x with{Amount=1},6=>x with{A=p.Known.Position},_=>x with{DirectiveCancellation=null}};string before=ContractJson.CanonicalHash(w);Assert.Equal(ResultCode.NotAvailable,s.DecideNewMilitary(x,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
 [Fact]public void DuplicateCancellationHasOneEffectAndOldSaveOmitsNewFields(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();Assert.DoesNotContain("DirectiveCancellation",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot())));Assert.Null(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation);var d=Cancel(s,root);var input=s.DiagnosticSnapshot().NewMilitary!.Requests.Last().Input;Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,0).Code);At(s,d.DueAt);Assert.Single(s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.Equal(ResultCode.AlreadyAccepted,s.DecideNewMilitary(input,s.PlayerControl,0).Code);new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void MissingReceiverCannotCreateCancellationEffectOrRevealPosition(){var s=Away();Send(s,NewMilitaryAction.RemoteRecall);At(s,s.DiagnosticSnapshot().NewMilitary!.Withdrawal!.Dispatches.Last().DueAt+5);var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var d=Cancel(s,root);var destination=d.Destination;At(s,d.DueAt);var w=s.DiagnosticSnapshot();Assert.False(w.NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single().Delivered);Assert.Empty(w.NewMilitary.UnitDirective.Cancellation.Effects);Assert.NotEqual(destination,NewGameMilitary.Position(w,1,s.Seconds));Assert.Equal("取消を発送：返書未受領",NewGameMilitary.UnitDirectiveCancellationStatus(w,root.Id));At(s,w.NewMilitary.UnitDirective.Cancellation.Receipts.Single().ReplyDueAt);Assert.Contains("不達報告",NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),root.Id));new WorldSession(s.DiagnosticSnapshot());}
 [Fact]public void ReturnedAuthorityDoesNotReappearAtFutureCancellationBoundary(){var s=Away();var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);long at=s.Seconds+180;var d=Cancel(s,root,at);At(s,d.DueAt);Send(s,NewMilitaryAction.Attach);Send(s,NewMilitaryAction.Enter);var w=s.DiagnosticSnapshot();Send(s,NewMilitaryAction.Unload,w.NewMilitary!.Moves.Sum(m=>m.Loading?m.Amount:-m.Amount)-w.NewMilitary.Uses.Sum(u=>u.Consumed));Send(s,NewMilitaryAction.Report);Send(s,NewMilitaryAction.Return);At(s,s.Seconds+3);Assert.Contains(s.DiagnosticSnapshot().NewMilitary!.Events,e=>e.Effect==MilitaryEffect.Returned);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,at);w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.AuthorityEnded,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);Assert.All(w.Units,u=>Assert.Equal(w.NewMilitary.Terms.Principal,u.Commander));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Fact]public void FutureEffectNoticeCanMissPersonAndBePhysicallyRecovered(){var s=Away();var anchor=NewGameMilitary.Anchor(s.DiagnosticSnapshot());MovePerson(s,new(anchor.X-20000,anchor.Y));var root=FailedOriginal(s,true,1,UnitDirectiveKind.Hold);HomeUnits(s);long at=s.Seconds+100;var d=Cancel(s,root,at);At(s,d.DueAt);var receipt=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Receipts.Single();At(s,receipt.ReplyDueAt);Assert.Contains("効力時刻を待つ",NewGameMilitary.UnitDirectiveCancellationStatus(s.DiagnosticSnapshot(),root.Id));MovePerson(s,new(anchor.X-40000,anchor.Y));At(s,at);var notice=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Cancellation!.Notices.Single();Assert.Contains(NewGameMilitary.CourierFrames(s.DiagnosticSnapshot(),s.Seconds),f=>f.Carrier==notice.Carrier&&f.Position==notice.Origin);At(s,notice.DueAt);var w=s.DiagnosticSnapshot();Assert.False(MessageFlow.Knows(w.Messaging,notice.Message,w.PlayerControl.Value));Assert.Contains("効力時刻を待つ",NewGameMilitary.UnitDirectiveCancellationStatus(w,root.Id));Assert.Contains(NewGameMilitary.HeldPapers(w,s.Seconds),h=>h.Message==notice.Message&&h.Holder==notice.Carrier);MovePerson(s,notice.Destination);Assert.True(NewGameMilitary.HeldAllowed(s.DiagnosticSnapshot(),NewMilitaryAction.TakeHeldReply));Send(s,NewMilitaryAction.TakeHeldReply);var t=s.DiagnosticSnapshot().NewMilitary!.HeldDelivery!.Transfers.Last();Assert.Equal(notice.Message,t.Message);var restored=new WorldSession(s.DiagnosticSnapshot());foreach(var v in new[]{s,restored})At(v,t.DueAt);w=s.DiagnosticSnapshot();Assert.True(MessageFlow.Knows(w.Messaging,notice.Message,w.PlayerControl.Value));Assert.Contains("未実行の対象原本を取消",NewGameMilitary.UnitDirectiveCancellationStatus(w,root.Id));Assert.Equal(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(restored.DiagnosticSnapshot()));new WorldSession(w);}
 [Fact]public void PendingNewerDirectiveRetainsItsIssuePriorityAfterOlderOriginalIsStopped(){var s=Away();var k=NewGameMilitary.SelectKnownTarget(s.DiagnosticSnapshot(),NewGameMilitary.UnitIds[1])!;MovePerson(s,k.Position);var i=Directive(s,1,UnitDirectiveKind.Move);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var root=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();var cancel=Cancel(s,root,root.DueAt+2);At(s,root.DueAt+1);var newer=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(newer,s.PlayerControl,s.Revision).Code);var d=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,Math.Max(d.DueAt,root.DueAt+2));var w=s.DiagnosticSnapshot();Assert.Equal(UnitCancelDisposition.Stopped,w.NewMilitary!.UnitDirective!.Cancellation!.Effects.Single().Outcome);var miss=w.NewMilitary.UnitDirective.Receipts.Single(r=>r.Id==d.Id);Assert.False(miss.Delivered);At(s,miss.ReplyDueAt);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(Retry(s,d),s.PlayerControl,s.Revision).Code);var copy=s.DiagnosticSnapshot().NewMilitary!.UnitDirective!.Dispatches.Last();At(s,copy.DueAt);w=s.DiagnosticSnapshot();Assert.True(w.NewMilitary!.UnitDirective!.Receipts.Single(r=>r.Id==copy.Id).Delivered);Assert.Equal(UnitDirectiveOutcome.Applied,w.NewMilitary.UnitDirective.Effects.Single(e=>e.Id==copy.Id).Outcome);new WorldSession(w);}
 [Fact]public void ExpiredCancellationDoesNotSuppressOriginal(){var s=Away();var i=Directive(s,1,UnitDirectiveKind.Hold);Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(i,s.PlayerControl,s.Revision).Code);var w=s.DiagnosticSnapshot();var root=w.NewMilitary!.UnitDirective!.Dispatches.Last();var p=new UnitDirectiveCancellationInput(NewGameMilitary.UnitDirectiveCancellationContract,root.Id,NewGameMilitary.SelectKnownTarget(w,root.Recipient)!,s.Seconds);var input=Input(s,NewMilitaryAction.CancelUnitDirective) with{DirectiveCancellation=p,DeliverBy=root.DueAt-1};Assert.Equal(ResultCode.Accepted,s.DecideNewMilitary(input,s.PlayerControl,s.Revision).Code);At(s,root.DueAt);w=s.DiagnosticSnapshot();Assert.Empty(w.NewMilitary!.UnitDirective!.Cancellation!.Effects);Assert.Equal(AttemptStatus.Rejected,w.Messaging.Attempts.Single(a=>a.Id==w.NewMilitary.UnitDirective.Cancellation.Dispatches.Single().Attempt).Status);Assert.Equal(UnitDirectiveOutcome.Applied,w.NewMilitary.UnitDirective.Effects.Single().Outcome);new WorldSession(w);}
}
